import sys, json

class Solution:
    def reinitializePermutation(self, n: int) -> int:
        perm = list(range(n))
        identity = list(range(n))
        operations = 0

        while True:
            arr = [0] * n
            for i in range(n):
                if i % 2 == 0:
                    arr[i] = perm[i // 2]
                else:
                    arr[i] = perm[n // 2 + (i - 1) // 2]
            perm = arr
            operations += 1
            if perm == identity:
                return operations

